def acquire(active, limits, pool):
    if pool not in limits:
        raise ValueError('unknown pool')
    if active.get(pool, 0) >= limits[pool]:
        return False
    active[pool] = active.get(pool, 0) + 1
    return True

def release(active, pool):
    if active.get(pool, 0) < 1:
        raise ValueError('nothing to release')
    active[pool] -= 1
